/**
 * test-pdf-chatgpt.ts — step Q.1: tests/fixtures/pdf/plan-chatgpt-flat.pdf, a two-bedroom flat
 * generated by ChatGPT (a reportlab script), NOT a real CAD export, read end to end and compared
 * with its trimmed truth (plan-chatgpt-flat.truth.json, millimetres, y north). No rule was tuned to
 * this file: every rule it relies on is a general convention proven on its own synthetic fixture
 * (scripts/test-pdf-conventions.ts). The expectations are HONEST: what is read now, and what is
 * still wrong, each asserted as it is so a change shows, and printed.
 *
 * Read correctly: every wall's centre line and thickness (to 0.5 mm, along the truth's lines; the
 * truth ends interior walls at faces, Atrium at centre lines); five doors (jambs, hinge jamb,
 * side), four windows; nine dimensions from bare numbers under "ALL DIMENSIONS IN mm", all OK;
 * the walls read entirely from the PDF (rule 8); furniture left out and reported.
 * Still wrong: the open passage is an unclassified door (there is no passage kind); Bathroom and
 * Kitchen are one room, because the drawing has no wall between them (a truth discrepancy).
 *
 * Run: npx tsx scripts/test-pdf-chatgpt.ts
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { analysePdfPage } from "../src/lib/pdf/analysePdf";
import { dimensionRows, modelRows } from "../src/lib/pdf/dimensions";
import { buildPdfPlan } from "../src/lib/pdf/snap";
import { wallLength } from "../src/lib/plan/geometry";
import { deriveRooms } from "../src/lib/plan/rooms";
import { validatePlan } from "../src/lib/plan/validate";
import type { Vec2 } from "../src/types/plan";
import { openNode, pdfjs, renderNode } from "./pdf-node";

const DIR = join(__dirname, "../tests/fixtures/pdf");
type P = [number, number];
const truth: {
  walls: { id: string; a: P; b: P; thickness: number }[];
  doors: { id: string; a: P; b: P; width: number; hinge: P }[];
  windows: { id: string; a: P; b: P; width: number }[];
  passages: { id: string; a: P; b: P; width: number }[];
  rooms: { name: string; min: P; max: P }[];
  dimensions: { id: string; value: number }[];
} = JSON.parse(readFileSync(join(DIR, "plan-chatgpt-flat.truth.json"), "utf8"));
const HALF_MM = 0.5; // millimetres here
const near = (p: P, q: P, tol = HALF_MM) => Math.hypot(p[0] - q[0], p[1] - q[1]) <= tol;

async function main() {
  const doc = await openNode(new Uint8Array(readFileSync(join(DIR, "plan-chatgpt-flat.pdf"))));
  const t0 = Date.now();
  const r = await analysePdfPage(pdfjs, await doc.getPage(1), { pageCount: 1, render: renderNode, ocr: async () => ({ labels: [], words: [], error: null, rereads: [] }) });
  await doc.loadingTask.destroy();
  const pxPerM = r.analysis.scale.pxPerM!;
  const b = buildPdfPlan(r.analysis, r.pdf, { pxPerM, source: "pdf" });
  const ms = Date.now() - t0;
  const c = b.coverage;
  // Plan metres -> the truth's millimetres (via page points; the page's frame is in the truth file).
  const mm = (p: Vec2): P => {
    const [xp, yp] = [(p.x + c.origin.x) / c.mPerPt, (p.y + c.origin.y) / c.mPerPt];
    return [(xp - 420) / 0.0283464567, (586.89 - yp) / 0.0283464567];
  };

  // ------------------------------------------------------------ scale and dimensions
  const s = r.pdf.scale!;
  assert.equal(r.pdf.kind, "vector");
  assert.equal(s.confidence, "good", `scale good (${s.reason})`);
  assert.ok(Math.abs(s.mPerPt! / s.title!.mPerPt - 1) < 0.0001, "the printed dimensions agree with the title block's 1:100");
  const rows = dimensionRows(s.matches, s.mPerPt!);
  assert.deepEqual(rows.map((x) => Math.round(x.printedM * 1000)).sort((p, q) => p - q), truth.dimensions.map((d) => d.value).sort((p, q) => p - q), "every printed dimension is a row");
  assert.ok(rows.every((x) => x.status === "ok"), "every dimension row OK");
  const model = modelRows(s.matches, b.plan, (x, y) => ({ x: x * c.mPerPt - c.origin.x, y: y * c.mPerPt - c.origin.y }), 3 / pxPerM);
  const modelOk = model.filter((x) => x.status === "ok").length;

  // ------------------------------------------------------------ walls
  assert.ok(c.pdfOnly && c.traced === 0 && c.exact === b.plan.walls.length, `walls read entirely from the PDF: ${c.exact} of ${c.walls}`);
  const built = b.plan.walls.map((w) => ({ a: mm(w.a), b: mm(w.b), t: w.thickness * 1000 }));
  for (const tw of truth.walls) {
    const h = Math.abs(tw.a[1] - tw.b[1]) < 1e-6;
    const [ac, al] = h ? [1, 0] : [0, 1];
    const on = built.filter((w) => Math.abs(w.t - tw.thickness) <= HALF_MM && Math.abs(w.a[ac] - tw.a[ac]) <= HALF_MM && Math.abs(w.b[ac] - tw.a[ac]) <= HALF_MM);
    const spans = on.map((w) => [w.a[al], w.b[al]].sort((p, q) => p - q)).sort((p, q) => p[0] - q[0]);
    const [s0, s1] = [tw.a[al], tw.b[al]].sort((p, q) => p - q);
    let reach = s0;
    for (const [p, q] of spans) if (p <= reach + HALF_MM) reach = Math.max(reach, q);
    assert.ok(reach >= s1 - HALF_MM, `${tw.id}: its centre line, ${tw.thickness} mm thick, is built from end to end`);
  }
  const offLine = built.filter((w) => !truth.walls.some((tw) => {
    const h = Math.abs(tw.a[1] - tw.b[1]) < 1e-6;
    const ac = h ? 1 : 0;
    return Math.abs(w.t - tw.thickness) <= HALF_MM && Math.abs(w.a[ac] - tw.a[ac]) <= HALF_MM && Math.abs(w.b[ac] - tw.a[ac]) <= HALF_MM;
  }));
  assert.deepEqual(offLine, [], "no wall off the truth's lines (furniture, dimensions, extension lines all left out)");

  // ------------------------------------------------------------ openings
  const ops = b.plan.openings.map((o) => {
    const w = b.plan.walls.find((x) => x.id === o.wallId)!;
    const L = wallLength(w);
    const at = (k: number): P => mm({ x: w.a.x + ((w.b.x - w.a.x) / L) * k, y: w.a.y + ((w.b.y - w.a.y) / L) * k });
    const [ja, jb] = [at(o.offset - o.width / 2), at(o.offset + o.width / 2)];
    // The leaf's side, in the truth's frame: the plan's (-dy, dx) normal for "left" (plan y down, truth y up).
    const n = { x: -(w.b.y - w.a.y) / L, y: (w.b.x - w.a.x) / L };
    const side: P = o.swing === "left" ? [n.x, -n.y] : [-n.x, n.y];
    return { o, ja, jb, hinge: o.hinge === "b" ? jb : ja, side };
  });
  const find = (a: P, bb: P) => ops.find((x) => (near(x.ja, a) && near(x.jb, bb)) || (near(x.ja, bb) && near(x.jb, a)));
  for (const d of truth.doors) {
    const x = find(d.a, d.b);
    assert.ok(x && x.o.kind === "door" && x.o.provenance === "vector", `${d.id}: a door read from the PDF, jambs within 0.5 mm`);
    // The truth's hinge point is on the face on the leaf's side, at the hinge jamb.
    const centre: P = [(d.a[0] + d.b[0]) / 2, (d.a[1] + d.b[1]) / 2];
    const along = Math.abs(d.a[0] - d.b[0]) > Math.abs(d.a[1] - d.b[1]) ? 0 : 1;
    assert.ok(Math.abs(x!.hinge[along] - d.hinge[along]) <= HALF_MM, `${d.id}: hung on the truth's hinge jamb`);
    const across = 1 - along;
    assert.ok(Math.sign(x!.side[across]) === Math.sign(d.hinge[across] - centre[across]), `${d.id}: opens to the truth's side`);
  }
  for (const w of truth.windows) {
    const x = find(w.a, w.b);
    assert.ok(x && x.o.kind === "window" && x.o.provenance === "vector", `${w.id}: a window read from the PDF, jambs within 0.5 mm`);
  }
  // Still wrong (honest): the open passage has no kind of its own; it is kept as an unclassified door.
  for (const p of truth.passages) {
    const x = find(p.a, p.b);
    assert.ok(x && x.o.kind === "door", `${p.id}: read at its exact jambs, as a door`);
    assert.ok(c.unclassifiedOpenings.length === 1, `${p.id}: flagged as unclassified ("Opening type not drawn; assumed door")`);
  }
  assert.equal(b.plan.openings.length, truth.doors.length + truth.windows.length + truth.passages.length, "no other opening");

  // ------------------------------------------------------------ rooms
  assert.deepEqual(validatePlan(b.plan), [], "validator clean");
  const rooms = deriveRooms(b.plan);
  const area = (name: string) => {
    const tr = truth.rooms.find((x) => x.name === name)!;
    return ((tr.max[0] - tr.min[0]) * (tr.max[1] - tr.min[1])) / 1e6;
  };
  for (const name of ["Bedroom 1", "Bedroom 2", "Hall", "Living"]) {
    const room = rooms.find((x) => x.name === name);
    assert.ok(room && Math.abs(room.area - area(name)) < 1e-4, `${name}: named, ${room?.area.toFixed(4)} m² against the truth's ${area(name).toFixed(4)} m²`);
  }
  // Still wrong, and right by the drawing: no wall is drawn between the bathroom and the kitchen.
  const merged = rooms.find((x) => x.name === "Bathroom / Kitchen");
  assert.ok(merged && rooms.length === 5, `Bathroom and Kitchen are one room (${rooms.map((x) => x.name).join(", ")})`);
  const strip = ((6658 - 6543) * (7770 - 5558)) / 1e6; // the 115 mm strip where the truth wants a wall
  assert.ok(Math.abs(merged.area - (area("Bathroom") + area("Kitchen") + strip)) < 1e-4, `Bathroom / Kitchen: ${merged.area.toFixed(4)} m², the two truth rooms plus the undrawn wall's strip`);

  // ------------------------------------------------------------ furniture, reported
  assert.ok(c.furniture.length >= 5, `furniture left out and reported (${c.furniture.length} groups)`);

  console.log(
    `plan-chatgpt-flat.pdf (ChatGPT-generated, not real CAD): walls ${c.exact} exact, ${c.traced} traced, read entirely from the PDF; ` +
      `openings ${c.openings.exact} exact of ${c.openings.total}, ${c.openings.traced} traced, 1 wrong type (the open passage, unclassified); ` +
      `doors ${truth.doors.length}/${truth.doors.length} with hinge and side right, windows ${truth.windows.length}/${truth.windows.length}; ` +
      `dimensions ${rows.length} read, ${rows.filter((x) => x.status !== "ok").length} flagged; model check ${modelOk}/${model.length} OK; ` +
      `rooms closed ${rooms.length} (${rooms.map((x) => `${x.name} ${x.area.toFixed(2)} m²`).join(", ")}); ` +
      `furniture reported: ${c.furniture.map((f) => `${f.kind} ${f.size.w.toFixed(2)} × ${f.size.d.toFixed(2)} m`).join(", ")}; ${(ms / 1000).toFixed(1)} s`,
  );
  console.log("still wrong: the open passage (no passage kind, an unclassified door); Bathroom and Kitchen one room (no wall drawn between them); heights are defaults");
  console.log("OK");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
